{
  "schema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "https://vomevolunteer.com/schemas/vome-studio-storyboard.json",
    "title": "Vome Studio storyboard",
    "description": "The contract between Vome OS and Vome Studio, and the one file a human edits to change a video. Everything a viewer hears or reads lives here: voiceover, captions, and on-screen text. NOTHING here is a timestamp. Timings are measured from the real voice track at build time and written to audio/vo/timing.json, because hand-maintained timings go stale the moment a word changes.",
    "type": "object",
    "required": [
      "id",
      "feature_name",
      "scenes"
    ],
    "additionalProperties": false,
    "properties": {
      "id": {
        "type": "string",
        "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$",
        "description": "Slug. Names the render folder and every output file."
      },
      "feature_name": {
        "type": "string",
        "description": "The feature as a volunteer manager would say it."
      },
      "source_faq_url": {
        "type": "string",
        "description": "The FAQ the script is checked against. Every claim must be supported by it."
      },
      "one_thing": {
        "type": "string",
        "description": "The single sentence a viewer should remember. If a scene does not serve this, cut the scene."
      },
      "aspects": {
        "type": "array",
        "items": {
          "enum": [
            "9x16",
            "4x5",
            "1x1",
            "16x9"
          ]
        },
        "description": "Formats to render. Omit for all four."
      },
      "voice": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "name": {
            "type": "string",
            "description": "ElevenLabs voice name, resolved at build time so a rebuilt voice keeps working."
          },
          "model": {
            "type": "string",
            "description": "The model matters as much as the voice. eleven_v4 and eleven_multilingual_v2 sound like different people."
          },
          "settings": {
            "type": "object",
            "properties": {
              "stability": {
                "type": "number",
                "minimum": 0,
                "maximum": 1
              },
              "similarity_boost": {
                "type": "number",
                "minimum": 0,
                "maximum": 1
              },
              "speed": {
                "type": "number",
                "minimum": 0.5,
                "maximum": 2
              }
            }
          }
        }
      },
      "music": {
        "type": "string",
        "description": "Path to the bed. Omit to use the synthesised pad."
      },
      "pacing": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "gap": {
            "type": "number",
            "default": 0.5,
            "description": "Seconds of air between spoken lines. The floor, not the target."
          },
          "lead_in": {
            "type": "number",
            "default": 0.3,
            "description": "Silence before the first word."
          },
          "tail": {
            "type": "number",
            "default": 3.5,
            "description": "Hold after the last word, for the end card."
          }
        }
      },
      "scenes": {
        "type": "array",
        "minItems": 1,
        "items": {
          "$ref": "#/$defs/scene"
        }
      }
    },
    "$defs": {
      "scene": {
        "type": "object",
        "required": [
          "id",
          "template"
        ],
        "additionalProperties": false,
        "properties": {
          "id": {
            "type": "string",
            "pattern": "^[a-z0-9_]+$"
          },
          "template": {
            "enum": [
              "hook",
              "problem",
              "ui_demo",
              "benefit",
              "cta"
            ],
            "description": "Which scene template renders this."
          },
          "lines": {
            "type": "array",
            "description": "Spoken lines, in order. One line is one TTS call: speech is synthesised per sentence, never per caption, because a fragment spoken in isolation has the wrong prosody.",
            "items": {
              "$ref": "#/$defs/line"
            }
          },
          "on_screen": {
            "type": "object",
            "description": "Text and mock content for this scene. Shape depends on the template.",
            "additionalProperties": true
          },
          "gap_before": {
            "type": "number",
            "description": "Extra seconds of air before this scene's first line, on top of the default gap. Use it to let a beat land."
          }
        }
      },
      "line": {
        "type": "object",
        "required": [
          "vo"
        ],
        "additionalProperties": false,
        "properties": {
          "vo": {
            "type": "string",
            "description": "What is spoken. May open with an audio tag in [square brackets] for eleven_v3/v4 delivery; tags are stripped for the local draft voice, which would read them aloud."
          },
          "captions": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "How the line is chunked on screen. Each chunk is placed across the line's measured duration by word count. An empty array means spoken but not captioned, which is right when on-screen type already carries the words."
          },
          "stack": {
            "type": "boolean",
            "description": "Build this line's caption chunks underneath each other instead of replacing: each stays on screen as the next appears, so a thought accumulates rather than flashing past. Use it where a sentence is doing real work. Keep a stack to three chunks: the plate grows upward and will eventually reach the content above it."
          },
          "cue": {
            "type": "string",
            "pattern": "^[a-z0-9_]+$",
            "description": "Names this line's start so an animation can hang off it. The composition reads cue times rather than hard-coded seconds, so re-recording the voice re-times the picture automatically."
          }
        }
      }
    }
  },
  "example": {
    "id": "recruitment-workflows",
    "feature_name": "Recruitment workflows",
    "source_faq_url": "https://support.vomevolunteer.com/portal/en/kb/articles/recruitment-workflows-on-vome",
    "one_thing": "You should not have to send every volunteer through the same long application form.",
    "voice": {
      "name": "Maya",
      "model": "eleven_v4",
      "settings": {
        "stability": 0.5,
        "similarity_boost": 0.75,
        "speed": 1.0
      }
    },
    "music": "audio/music/Bright_Focus.wav",
    "pacing": {
      "gap": 0.5,
      "lead_in": 0.3,
      "tail": 3.5
    },
    "scenes": [
      {
        "id": "hook",
        "template": "hook",
        "lines": [
          {
            "vo": "[calm, measured] Still sending every volunteer through the same application form?",
            "captions": []
          }
        ],
        "on_screen": {
          "lines": [
            "Still sending",
            "*every volunteer*",
            "through the same",
            "application form?"
          ]
        }
      },
      {
        "id": "problem",
        "template": "problem",
        "lines": [
          {
            "vo": "A 13 year old may need parental consent.",
            "captions": [
              "A *13 year old* may need parental consent."
            ],
            "cue": "form_in"
          },
          {
            "vo": "Whereas a returning volunteer does not need to reapply.",
            "captions": [
              "Whereas a *returning volunteer*",
              "does not need to reapply."
            ],
            "cue": "badge_in"
          },
          {
            "vo": "But everyone is still getting the same long form.",
            "captions": [
              "But *everyone* is still getting",
              "the same long form."
            ],
            "cue": "tags_in"
          }
        ],
        "on_screen": {
          "chip": "Application",
          "title": "General Application Form",
          "badge": "42 questions",
          "fields": [
            {
              "label": "Full name"
            },
            {
              "label": "Date of birth"
            },
            {
              "label": "Emergency contact"
            },
            {
              "label": "Driver's licence number",
              "tag": "Not relevant"
            },
            {
              "label": "Vehicle insurance provider",
              "tag": "Not relevant"
            },
            {
              "label": "Previous volunteer experience"
            },
            {
              "label": "Parent or guardian signature",
              "tag": "Not relevant"
            },
            {
              "label": "T-shirt size"
            },
            {
              "label": "Dietary restrictions"
            }
          ]
        }
      },
      {
        "id": "ui_demo",
        "template": "ui_demo",
        "lines": [
          {
            "vo": "Vome lets you build recruitment workflows based on your path.",
            "stack": true,
            "captions": [
              "*Vome* lets you build",
              "recruitment workflows",
              "based on your path."
            ],
            "cue": "card_in"
          },
          {
            "vo": "[curious] Under eighteen? Send them to the minor application.",
            "captions": [
              "Under 18?",
              "Send them to the minor application."
            ],
            "cue": "rule1"
          },
          {
            "vo": "[curious] Already approved elsewhere? Register them instantly.",
            "captions": [
              "Already approved elsewhere?",
              "Register them instantly."
            ],
            "cue": "rule2"
          },
          {
            "vo": "Everyone else gets the general form.",
            "captions": [
              "Everyone else gets the general form."
            ],
            "cue": "rule3"
          },
          {
            "vo": "Rules run top to bottom, and the first match wins.",
            "captions": [
              "Rules run top to bottom,",
              "and the first match wins."
            ],
            "cue": "match"
          }
        ],
        "on_screen": {
          "chip": "Recruitment",
          "title": "Food Bank Driver",
          "status": "On",
          "label": "Dynamic workflow",
          "applicant": {
            "initials": "PO",
            "name": "Priya O., 16"
          },
          "rules": [
            {
              "condition": "Age under 18",
              "action": "Submit a Vome form",
              "action_kind": "form",
              "meta": "Minor Application Form"
            },
            {
              "condition": "Approved in same category",
              "action": "Auto-approve opportunity",
              "action_kind": "auto"
            },
            {
              "condition": "Everyone (catch-all)",
              "action": "Submit a Vome form",
              "action_kind": "form",
              "meta": "General Application Form"
            }
          ]
        }
      },
      {
        "id": "benefit",
        "template": "benefit",
        "gap_before": 1.2,
        "lines": [
          {
            "vo": "[warm] Every volunteer gets the shortest path.",
            "captions": [],
            "cue": "benefit_in"
          }
        ],
        "on_screen": {
          "lines": [
            "Every volunteer gets",
            "*the shortest path.*"
          ],
          "routes": [
            "Under 18",
            "Returning",
            "Everyone else"
          ]
        }
      },
      {
        "id": "cta",
        "template": "cta",
        "gap_before": 2.5,
        "lines": [
          {
            "vo": "[confident] Build yours in Vome. [warm] Build your first form free.",
            "stack": true,
            "captions": [
              "Build yours in Vome.",
              "*Build your first form free.*"
            ],
            "cue": "cta_in"
          }
        ],
        "on_screen": {
          "tagline": [
            "The volunteer management software",
            "*your volunteers and staff*",
            "actually want to use"
          ],
          "url": "vomevolunteer.com"
        }
      }
    ]
  },
  "required_cues": [
    "badge_in",
    "benefit_in",
    "card_in",
    "cta_in",
    "match",
    "rule1",
    "rule2",
    "rule3",
    "tags_in"
  ],
  "templates": [
    "hook",
    "problem",
    "ui_demo",
    "benefit",
    "cta"
  ]
}

