  "schema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "https://vomevolunteer.com/schemas/vome-studio-storyboard.json",
    "title": "Vome Studio storyboard",
    "description": "The contract between Vome OS and Vome Studio, and the one file a human edits to change a video. Everything a viewer hears or reads lives here: voiceover, captions, and on-screen text. NOTHING here is a timestamp. Timings are measured from the real voice track at build time and written to audio/vo/timing.json, because hand-maintained timings go stale the moment a word changes.",
    "type": "object",
    "required": [
      "id",
      "feature_name",
      "scenes"
    ],
    "additionalProperties": false,
    "properties": {
      "id": {
        "type": "string",
        "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$",
        "description": "Slug. Names the render folder and every output file."
      },
      "feature_name": {
        "type": "string",
        "description": "The feature as a volunteer manager would say it."
      },
      "source_faq_url": {
        "type": "string",
        "description": "The FAQ the script is checked against. Every claim must be supported by it."
      },
      "one_thing": {
        "type": "string",
        "description": "The single sentence a viewer should remember. If a scene does not serve this, cut the scene."
      },
      "aspects": {
        "type": "array",
        "items": {
          "enum": [
            "9x16",
            "4x5",
            "1x1",
            "16x9"
          ]
        },
        "description": "Formats to render. Omit for all four."
      },
      "voice": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "name": {
            "type": "string",
            "description": "ElevenLabs voice name, resolved at build time so a rebuilt voice keeps working."
          },
          "model": {
            "type": "string",
            "description": "The model matters as much as the voice. eleven_v4 and eleven_multilingual_v2 sound like different people."
          },
          "settings": {
            "type": "object",
            "properties": {
              "stability": {
                "type": "number",
                "minimum": 0,
                "maximum": 1
              },
              "similarity_boost": {
                "type": "number",
                "minimum": 0,
                "maximum": 1
              },
              "speed": {
                "type": "number",
                "minimum": 0.5,
                "maximum": 2
              }
            }
          }
        }
      },
      "music": {
        "type": "string",
        "description": "Path to the bed. Omit to use the synthesised pad."
      },
      "pacing": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "gap": {
            "type": "number",
            "default": 0.5,
            "description": "Seconds of air between spoken lines. The floor, not the target."
          },
          "lead_in": {
            "type": "number",
            "default": 0.3,
            "description": "Silence before the first word."
          },
          "tail": {
            "type": "number",
            "default": 3.5,
            "description": "Hold after the last word, for the end card."
          }
        }
      },
      "scenes": {
        "type": "array",
        "minItems": 1,
        "items": {
          "$ref": "#/$defs/scene"
        }
      }
    },
    "$defs": {
      "scene": {
        "type": "object",
        "required": [
          "id",
          "template"
        ],
        "additionalProperties": false,
        "properties": {
          "id": {
            "type": "string",
            "pattern": "^[a-z0-9_]+$"
          },
          "template": {
            "enum": [
              "hook",
              "problem",
              "ui_demo",
              "benefit",
              "cta"
            ],
            "description": "Which scene template renders this."
          },
          "lines": {
            "type": "array",
            "description": "Spoken lines, in order. One line is one TTS call: speech is synthesised per sentence, never per caption, because a fragment spoken in isolation has the wrong prosody.",
            "items": {
              "$ref": "#/$defs/line"
            }
          },
          "on_screen": {
            "type": "object",
            "description": "Text and mock content for this scene. Shape depends on the template.",
            "additionalProperties": true
          },
          "gap_before": {
            "type": "number",
            "description": "Extra seconds of air before this scene's first line, on top of the default gap. Use it to let a beat land."
          }
        }
      },
      "line": {
        "type": "object",
        "required": [
          "vo"
        ],
        "additionalProperties": false,
        "properties": {
          "vo": {
            "type": "string",
            "description": "What is spoken. May open with an audio tag in [square brackets] for eleven_v3/v4 delivery; tags are stripped for the local draft voice, which would read them aloud."
          },
          "captions": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "How the line is chunked on screen. Each chunk is placed across the line's measured duration by word count. An empty array means spoken but not captioned, which is right when on-screen type already carries the words."
          },
          "stack": {
            "type": "boolean",
            "description": "Build this line's caption chunks underneath each other instead of replacing: each stays on screen as the next appears, so a thought accumulates rather than flashing past. Use it where a sentence is doing real work. Keep a stack to three chunks: the plate grows upward and will eventually reach the content above it."
          },
          "cue": {
            "type": "string",
            "pattern": "^[a-z0-9_]+$",
            "description": "Names this line's start so an animation can hang off it. The composition reads cue times rather than hard-coded seconds, so re-recording the voice re-times the picture automatically."
          }
        }
      }
    }
  },
